import nodemailer from 'nodemailer';
import Handlebars from 'handlebars';
const transport = nodemailer.createTransport({ host: '{{smtp_host}}', port: 587, auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS } });
const tpl = Handlebars.compile('<p>Hi {{name}}, your code: {{code}}</p>');
await transport.sendMail({ from: '{{from}}', to, subject: 'Verify', html: tpl({ name, code }) });
